INSERT INTO `audit` (`id`, `name`, `type`, `delete_flag`, `create_time`, `update_time`, `status`, `execution_time`, `service_type`, `account`, `password`, `service_address`, `email`) VALUES (11, '第三方资源网址内容审核', 2, 0, '2024-12-01 20:48:24', '2025-03-17 14:56:02', 0, '', 0, 'root', 'root', '127.0.0.1', NULL);
INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (1, '哈利·波特', '9787020096695', 493, 7, NULL, 'J.K.罗琳', 498.00, 3104, '精装', '2008-12-01 08:00:00', 'J. K. 罗琳（J. K. Rowling， 1965- ），英国女作家，自小喜欢写作，当过短时间的教师和秘书。二十四岁那年，她在前往伦敦的火车旅途中萌生了创作“哈利·波特”系列小说的念头。七年后，《哈利·波特与魔法石》问世，之后她陆续创作了《哈利·波特与密室》《哈 利·波特与阿兹卡班囚徒》《哈利·波特与火焰杯》《哈利-波特与凤凰社》《哈利·波特与“混血王子”》和《哈利·波特与死亡圣器》，完成了该系列的创作，在全球刮起一股股“哈利·波特”飓风，在世界范围内掀起规模宏大的“哈利·波特”阅读狂潮。另外，在此期间，她还因为慈善事业而先后完成了《神奇动物在哪里》和《神奇的魁地奇球》这两部与“哈利·波特”系列相关的图书。\n\n2012年推出首部成人长篇小说《偶发空缺》。\n\nJ. K. 罗琳与她的丈夫及三个孩子生活在爱丁堡，一边尽享家庭生活的幸福，一边文学创作。', '《哈利·波特(共7册)(精)》编著者J.K.罗琳。\n\n《哈利·波特(共7册)(精)》内容提要：2000年的一个深夜，在美国书店的烛光中，穿着黑斗篷，戴着小眼镜的店员开始销售“哈利o波特4”英文版，从此哈利·波特系列图书席卷全球，也是在这一年，简体中文版“哈利o波特”系列图书通过人民文学出版社引进版权登陆中国，作者J.K.罗琳用一种简单的魔法游戏将魔幻的故事传递给了中国乃至全球的青少年读者，与此同时商业电影的改编更是将这部魔幻题材的小说推向了巅峰。\n\n截止到2013年，哈利·波特系列图书累计销量达到200多万套。\n\n此次，人民文学出版社隆重推出《哈利o波特（精装本）》（全七册），此套精装珍藏版《哈利·波特》听取广大资深哈迷的心声，恢复选用陪伴广大哈迷十年之久深入人心的原有封面，并在此基础上提高工艺、完善装帧，配有独具匠心的精美函套，使哈利波特系列7本浑然一体，必将成为每一个喜欢哈利·波特读者爱不释手的珍藏！\n\n', 'http://demo.dianhuiyun.com.cn/dsh-client-h5/#/pages/forum/forum?id=1&type=1', 'http://8.153.16.66:9000/dsh/c49ee6cdf2ee435a98f6e0e8e1e2fbf3.jpg', 0, '2024-10-25 11:30:05', '2024-10-25 12:24:05', NULL, NULL, 0);
INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (2, '红楼梦', '9787020002207', 511, 3, NULL, '曹雪芹', 59.70, 1606, '平装', '1996-12-01 08:00:00', '曹雪芹,（？-1763，一作1764）清小说家。名霑，字梦阮，号雪芹、芹圃、芹溪。为满洲正白旗“包衣”人。自曾祖起，三代任江宁织造，其祖曹寅尤为康熙帝所信用。雍正初年，在统计阶级内部政治斗争牵连下，雪芹家受到重大打击，其父免职，产业被抄，遂随家迁居北京。他早年经历了一段封建大官僚地主家庭的繁华生活，后因家道衰落，趋于艰困。晚期居北京西郊，贫病而卒，年未及五十。性情高傲，嗜酒健谈。', '《红楼梦》是一部百科全书式的长篇小说。以宝黛爱情悲剧为主线，以四大家族的荣辱兴衰为背景，描绘出18世纪中国封建社会的方方面面，以及封建专制下新兴资本主义民主思想的萌动。结构宏大、情节委婉、细节精致，人物形象栩栩如生，声口毕现，堪称中国古代小说中的经 典。', 'http://demo.dianhuiyun.com.cn/dsh-client-h5/#/pages/forum/forum?id=2&type=1', 'http://8.153.16.66:9000/dsh/de7d8f325aa347279fe1172c9d6dcbb3.jpg', 0, '2024-10-25 11:33:32', '2024-10-25 11:38:39', NULL, NULL, 0);
INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (3, '1984', '9787530210291', 8, 7, NULL, '乔治·奥威尔', 54.00, 304, '精装', '2010-04-01 08:00:00', '乔治•奥威尔（1903-1950）， 英国著名作家。主要作品有《动物农场》、《1984》等。\n\n1903年出生于印度，1907年举家迁回英国，后因经济原因无力深造，被迫远走缅甸，参加帝国警察部队。终因厌倦殖民行径、痴迷写作而辞去公职，辗转回到欧洲，流亡伦敦、巴黎等地，一边深刻体验下层民众生活，一遍从事文学创作，有多部作品出版。1936年西班牙内战爆发，参加左翼组织，因重伤返回英国，但最终树立社会主义信念。1939年，二战爆发，积极参加反纳粹的活动。由于西班牙内战与二战的苦痛经历，对战争与和平、极权与民主、社会关怀与人类理想进行了深刻的思考。\n\n1945年，著名的政治寓言小说《动物农场》出版。1949年，《1984》问世，在全球产生深远影响。作品入选多国中学生必读书目，被翻译成62种文字，总销量超过5000万册。\n\n1950年，因肺病去世，年仅47岁。', '《1984》是一部杰出的政治寓言小说，也是一部幻想小说。作品刻画了人类在极权主义社会的生存状态，有若一个永不褪色的警示标签，警醒世人提防这种预想中的黑暗成为现实。历经几十年，其生命力益显强大，被誉为20世纪影响最为深远的文学经典之一。', 'http://demo.dianhuiyun.com.cn/dsh-client-h5/#/pages/forum/forum?id=3&type=1', 'http://8.153.16.66:9000/dsh/9a16a849991644f398a5225f321ac893.jpg', 0, '2024-10-25 11:37:01', '2024-10-25 12:24:10', NULL, NULL, 0);
INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (4, '活着', '9787506365437', 511, 4, NULL, '余华', 20.00, 191, '平装', '2012-08-01 08:00:00', '余华，1960年出生，1983年开始写作。至今已经出版长篇小说4部，中短篇小说集6部，随笔集4部。主要作品有《兄弟》《活着》《许三观卖血记》《在细雨中呼喊》等。', '《活着(新版)》讲述了农村人福贵悲惨的人生遭遇。福贵本是个阔少爷，可他嗜赌如命，终于赌光了家业，一贫如洗。他的父亲被他活活气死，母亲则在穷困中患了重病，福贵前去求药，却在途中被国民党抓去当壮丁。经过几番波折回到家里，才知道母亲早已去世，妻子家珍含辛茹苦地养大两个儿女。此后更加悲惨的命运一次又一次降临到福贵身上，他的妻子、儿女和孙子相继死去，最后只剩福贵和一头老牛相依为命，但老人依旧活着，仿佛比往日更加洒脱与坚强。', 'http://demo.dianhuiyun.com.cn/dsh-client-h5/#/pages/forum/forum?id=5&type=1', 'http://8.153.16.66:9000/dsh/9e6fb861d28f44968b9ce2c51762a353.jpg', 0, '2024-10-25 11:42:39', '2024-10-25 12:28:32', NULL, NULL, 0);
INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (5, '百年孤独', '9787544253994', 514, 8, NULL, '加西亚·马尔克斯', 39.50, 360, '精装', '2011-10-06 08:00:00', '加西亚•马尔克斯（Gabriel García Márquez）1927年出生于哥伦比亚马格达莱纳海滨小镇阿拉卡塔卡。童年与外祖父母一起生活。1936年随父母迁居苏克雷。1947年考入波哥大国立大学。1948年因内战辍学，进入报界。五十年代开始发表文学作品。六十年代初移居墨西哥。1967年出版《百年孤独》。1982年获诺贝尔文学奖。', '《百年孤独》是魔幻现实主义文学的代表作，描写了布恩迪亚家族七代人的传奇故事，以及加勒比海沿岸小镇马孔多的百年兴衰，反映了拉丁美洲一个世纪以来风云变幻的历史。作品融入神话传说、民间故事、宗教典故等神秘因素，巧妙地糅合了现实与虚幻，展现出一个瑰丽的想象世界，成为20世纪最重要的经典文学巨著之一。1982年加西亚•马尔克斯获得诺贝尔文学奖，奠定世界级文学大师的地位，很大程度上乃是凭借《百年孤独》的巨大影响。', 'http://demo.dianhuiyun.com.cn/dsh-client-h5/#/pages/forum/forum?id=6&type=1', 'http://8.153.16.66:9000/dsh/45438407616b46689e50621c66dd3a1f.jpg', 0, '2024-10-25 12:16:01', '2024-10-25 12:35:51', NULL, NULL, 0);
INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (6, '飘', '9787806570920', 603, 8, NULL, '玛格丽特·米切尔', 40.00, 1235, '平装', '2000-09-08 08:00:00', '米切尔（Margaret Mitchell, 1900-1949）美国女作家。出生于美国南部佐治亚州亚特兰大市。父亲是个律师，曾任亚特兰大历史协会主席。米切尔曾就读于华盛顿神学院、马萨诸塞州的史密斯学院。其后，她曾担任地方报纸《亚特兰大报》的记者。1925年与约翰·马尔什结婚，婚后辞去报职，潜心写作。\n\n米切尔一生中只发表了《飘》这部长篇巨著。她从1926年开始着力创作《飘》，10 年之后，作品问世，一出版就引起了强烈的反响。\n\n由于家庭的熏陶，米切尔对美国历史，特别是南北战争时期美国南方的历史产生了浓厚的兴趣。她在家乡听闻了大量有关内战和战后重建时期的种种轶事和传闻，接触并阅读了大量有关内战的书籍。她自幼在南部城市亚特兰大成长，耳濡目染了美国南方的风土人情，这里的自然环境和社会环境成了米切尔文思纵横驰骋的背景和创作的源泉.', '小说中的故事发生在1861年美国南北战争前夕。生活在南方的少女郝思嘉从小深受南方文化传统的熏陶，可在她的血液里却流淌着野性的叛逆因素。随着战火的蔓廷和生活环境的恶化，郝思嘉的叛逆个性越来越丰满，越鲜明，在一系列的的挫折中她改造了自我，改变了个人甚至整个家族的命运，成为时代时势造就的新女性的形象。\n\n作品在描绘人物生活与爱情的同时，勾勒出南北双方在政治，经济，文化各个层次的异同，具有浓厚的史诗风格，堪称美国历史转折时期的真实写照，同时也成为历久不衰的爱情经典。', 'http://demo.dianhuiyun.com.cn/dsh-client-h5/#/pages/forum/forum?id=8&type=1', 'http://8.153.16.66:9000/dsh/872f584c27034d8a9b63e425857f19d2.jpg', 0, '2024-10-25 12:20:17', '2024-10-25 12:36:57', NULL, NULL, 0);
INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (7, 'Java编程思想 （第4版）', '9787111213826', 5, 3, '陈昊鹏', 'Thinking in Java', 108.00, 880, NULL, '2007-06-01 08:00:00', 'Bruce Eckel是MindView公司（www.MindView.net）的总裁，该公司向客户提供软件咨询和培训。他是C++标准委员会拥有表决权的成员之一，拥有应用物理学学士和计算机工程硕士学位。除本书外，他还是《C++编程思想》的作者，并与人合著了《C++编程思想 第2卷》（这两本书的英文影印版及中文版均已由机械工业出版社引进出版）及其他著作。他已经发表了150多篇论文，还经常参加世界各地的研讨会并进行演讲。', '本书赢得了全球程序员的广泛赞誉，即使是最晦涩的概念，在Bruce Eckel的文字亲和力和小而直接的编程示例面前也会化解于无形。从Java的基础语法到最高级特性（深入的面向对象概念、多线程、自动项目构建、单元测试和调试等），本书都能逐步指导你轻松掌握。\n\n从本书获得的各项大奖以及来自世界各地的读者评论中，不难看出这是一本经典之作。本书的作者拥有多年教学经验，对C、C++以及Java语言都有独到、深入的见解，以通俗易懂及小而直接的示例解释了一个个晦涩抽象的概念。本书共22章，包括操作符、控制执行流程、访问权限控制、复用类、多态、接口、通过异常处理错误、字符串、泛型、数组、容器深入研究、Java I/O系统、枚举类型、并发以及图形化用户界面等内容。这些丰富的内容，包含了Java语言基础语法以及高级特性，适合各个层次的Java程序员阅读，同时也是高等院校讲授...', 'http://demo.dianhuiyun.com.cn/dsh-client-h5/#/pages/forum/forum?id=4&type=1', 'http://8.153.16.66:9000/dsh/75bc564f3e72454c873d461de41c1792.jpg', 0, '2024-10-25 12:24:13', '2024-10-25 12:26:54', NULL, NULL, 0);
INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (8, '动物农场', '9787532741854', 4, 8, NULL, ' [英国] 乔治·奥威尔', 10.00, 119, '平装', '2007-03-21 08:00:00', '治·奥威尔（George Orwell），本名埃里克·亚瑟·布莱尔（Eric Arthur Blair）。1903年生于印度，当时，他的父亲在当地的殖民地政府供职，用他自己的话说，他家属于“中产阶级的下层，或没有钱财的中产家庭”。\n\n1904年，由母亲带他先回到了英国。他自幼天资聪颖，11岁时就在报纸上发表了一篇诗作《醒来吧，英格兰的小伙子们》。14岁又考入著名的伊顿（Eton）公学，并获取了奖学金。但早在小学时期，他就饱尝了被富家子弟歧视的苦涩，从他后来的回顾中可以看出，凭他那天生就很敏感的心灵，这时已经对不平等有了初步的体验....', '《动物农场》是奥威尔最优秀的作品之一，是一则入木三分的反乌托的政治讽喻寓言。\n\n农场的一群动物成功地进行了一场“革命”，将压榨他们的人类东家赶出农场，建立起一个平等的动物社会。然而，动物领袖，那些聪明的猪们最终却篡夺了革命的果实，成为比人类东家更加独裁和极权的统治者。', 'http://demo.dianhuiyun.com.cn/dsh-client-h5/#/pages/forum/forum?id=9&type=1', 'http://8.153.16.66:9000/dsh/362a854b6743493b80a4cb60a13c4df8.jpg', 0, '2024-10-25 12:28:47', '2024-10-25 12:38:00', NULL, NULL, 0);
INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (9, '白夜行', '9787544258609', 522, 7, NULL, ':[日] 东野圭吾', 39.50, 538, '精装', '2013-01-01 08:00:00', '东野圭吾\n\n日本著名作家。\n\n1985年，凭《放学后》获第31届江户川乱步奖，开始专职写作；\n\n1999年，《秘密》获第52届日本推理作家协会奖；此后《白夜行》、《单恋》、《信》、《幻夜》先后入围直木奖。\n\n2005年出版的《嫌疑人X的献身》史无前例地将第134届直木奖、第6届本格推理小说大奖，以及年度三大推理小说排行榜第1名一并斩获；\n\n2008年，《流星之绊》获第43届新风奖。\n\n2009年出版的《新参者》获两大推理小说排行榜年度第1名；\n\n2012年，《浪矢杂货店的奇迹》获第7届中央公论文艺奖。', '东野圭吾万千书迷心中的无冕之王\n\n周刊文春推理小说年度BEST10第1名\n\n本格推理小说年度BEST10第2名\n\n《白夜行》是东野圭吾迄今口碑最好的长篇杰作，具备经典名著的一切要素：\n\n一宗离奇命案牵出跨度近20年步步惊心的故事：悲凉的爱情、吊诡的命运、令人发指的犯罪、复杂人性的对决与救赎……\n\n-------------------------------------------------------------------\n\n1973年，大阪的一栋废弃建筑中发现一名遭利器刺死的男子。案件扑朔迷离，悬而未决。\n\n此后20年间，案件滋生出的恶逐渐萌芽生长，绽放出恶之花。案件相关者的人生逐渐被越来越重的阴影笼罩……\n\n“我的天空里没有太阳，总是黑夜，但并不暗，因为有东西代替了太阳。虽然没有太阳那么明亮，但对我来说已经足够。\n\n凭借着这份光，我便能把黑夜当成白天。\n\n我从...', 'http://demo.dianhuiyun.com.cn/dsh-client-h5/#/pages/forum/forum?id=10&type=1', 'http://8.153.16.66:9000/dsh/793d4934cc104496bea2a75f33bc43b9.jpg', 0, '2024-10-25 12:30:34', '2024-10-25 12:38:41', NULL, NULL, 0);
INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (10, '杀死一只知更鸟', '9787544722766', 516, 3, NULL, ' [美国] 哈珀·李', 32.00, 346, '精装', '2012-09-14 08:00:00', '哈珀•李（1926— ）\n\n生于美国阿拉巴马州， 曾被授予普利策小说奖及其他众多文学奖项。她与杜鲁门•卡坡蒂是幼年的邻居和一生的朋友。《杀死一只知更鸟》据说是以卡坡蒂为原型之一创作的，现已成为公认的美国文学经典。此后，她一直隐居在家乡亚拉巴马的小镇上 ，拒绝各种采访，过着平静的生活。有人问她为什么不在盛名之下接着写作，她回答：“有过这样一次，还有什么可写的？”', '成长总是个让人烦恼的命题。成长有时会很缓慢，如小溪般唱着叮咚的歌曲趟过，有时却如此突如其来，如暴雨般劈头盖脸……三个孩子因为小镇上的几桩冤案经历了猝不及防的成长——痛苦与迷惑，悲伤与愤怒，也有温情与感动。这是爱与真知的成长经典。\n\n《杀死一只知更鸟》获1961年普利策奖。\n\n美国图书馆借阅率最高的书，英国青少年最喜爱的小说之一。\n\n美国中学推荐课外读物。\n\n由小说改编的电影获第25届奥斯卡三项大奖。\n\n美国电影协会评选的“100名银幕英雄与恶人”中，派克主演的芬奇律师名列英雄第一位。\n\n作为史上最受喜爱的小说之一，《杀死一只知更鸟》已获得显赫声誉。它赢得过普利策奖，被翻译成四十多种语言，在世界范围内售出超过三千万册，并曾被拍成，备受欢迎的电影。\n\n——哈珀•柯林斯出版集团', 'http://demo.dianhuiyun.com.cn/dsh-client-h5/#/pages/forum/forum?id=11&type=1', 'http://8.153.16.66:9000/dsh/bb7677cfa1c14d23ae73250bd475e099.jpg', 0, '2024-10-25 12:32:09', '2024-10-25 12:39:30', NULL, NULL, 0);
INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (16, '三体全集', '9787229042066', 511, 8, NULL, '刘慈欣', 168.00, 1285, '精装', '2012-01-01 08:00:00', '刘慈欣，祖籍河南，长于山西，中国科普作家协会会员，山西省作家协会会员，高级工程师\n自1999年处女作《鲸歌》问世以来，发表短篇科幻小说三十余篇，出版长篇科幻小说七部，并创下连续八年荣获中国科幻最高奖“银河奖”的纪录。其气势恢宏的“地球往事”系列第一部《三体》开创了《科幻世界》月刊连载原创作品之先河，一举成为2006年度最受关注、最畅销的科幻小说。2008年，“地球往事”系列第二部《黑暗森林》面世，再次成为当年最畅销的科幻小说。2010年，“地球往事”系列第三部《死神永生》出版，一举拿下该年度中国科幻“银河奖”特别奖、全球华语科幻“星云奖”最佳长篇奖。刘慈欣亦因此被评论界誉为“21世纪中国文坛最值得关注的作家”。', '文化大革命如火如荼进行的同时，军方探寻外星文明的绝秘计划“红岸工程”取得了突破性进展。但在按下发射键的那一刻，历经劫难的叶文洁没有意识到，她彻底改变了人类的命运。\n\n地球文明向宇宙发出的第一声啼鸣，以太阳为中心，以光速向宇宙深处飞驰……\n\n四光年外，“三体文明”正苦苦挣扎——三颗无规则运行的太阳主导下的百余次毁灭与重生逼迫他们逃离母星。而恰在此时，他们接收到了地球发来的信息。\n\n在运用超技术锁死地球人的基础科学之后，三体人庞大的宇宙舰队开始向地球进发……人类的末日悄然来临。', 'http://demo.dianhuiyun.com.cn/dsh-client-h5/#/pages/forum/forum?id=7&type=1', 'http://8.153.16.66:9000/dsh/ebbaefbf18104849b00a96e408f97801.jpg', 0, '2024-10-25 12:33:27', '2024-10-25 12:36:44', NULL, NULL, 0);
INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (17, '局外人', '9787532751471', 514, 3, NULL, ' [法] 阿尔贝·加缪', 22.00, 128, '精装', '2010-08-19 08:00:00', '阿尔贝·加缪（Albert Camus，1913—1960），法国声名卓著的小说家、散文家和剧作家，“存在主义”文学的大师。1957年因“热情而冷静地阐明了当代向人类良知提出的种种问题”而获诺贝尔文学奖，是有史以来最年轻的诺奖获奖作家之一。加缪在他的小说、戏剧、随笔和论著中深刻地揭示出人在异己的世界中的孤独、个人与自身的日益异化，以及罪恶和死亡的不可避免，但他在揭示出世界的荒诞的同时却并不绝望和颓丧，他主张要在荒诞中奋起反抗，在绝望中坚持真理和正义，他为世人指出了一条基督教和马克思主义以外的自由人道主义道路。他直面惨淡人生的勇气，他“知其不可而为之”的大无畏精神使他在第二次世界大战之后不仅在法国，而且在欧洲并最终在全世界成为他那一代人的代言人和下一代人的精神导师。', '《局外人》是法国作家加缪的成名作，同时也是存在主义文学的杰出作品之一，该书以一种客观记录式的“零度风格”，粗线条地描述了主人公默尔索在荒谬的世界中经历的种种荒谬的事，以及自身的荒诞体验。从参加母亲的葬礼到偶然成了杀人犯，再到被判处死刑，默尔索似乎对一切都无动于衷，他像一个象征性的符号，代表了一种普遍的存在，又像是一个血红色的灯塔，具有高度的警示性。然而，局外人现象的产生无疑是由这个世界本身所孕育的，默尔索的存在有其深刻的外部原因。', 'http://demo.dianhuiyun.com.cn/dsh-client-h5/#/pages/forum/forum?id=13&type=1', 'http://8.153.16.66:9000/dsh/f3add770467d4f92b4b7f265ddcbe9f7.jpg', 0, '2024-10-25 12:34:28', '2024-10-25 12:40:24', NULL, NULL, 0);
INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (18, '房思琪的初恋乐园', '9787559614636', 511, 3, NULL, '林奕含', 45.00, 272, '平装', '2018-02-01 08:00:00', '林奕含（1991——2017），台湾作家。出生于台南，曾居台北。梦想是一面写小说，一面像大江健三郎所说的：从书呆子变成读书人，再从读书人变成知识分子。', '令人心碎却无能为力的真实故事。\n\n向死而生的文学绝唱 打动万千读者的年度华语小说。\n\n李银河 戴锦华 骆以军 张悦然 詹宏志 蒋方舟 等多位学者作家社会名人郑重推荐。\n\n痛苦的际遇是如此难以分享，好险这个世界还有文学。', 'http://demo.dianhuiyun.com.cn/dsh-client-h5/#/pages/forum/forum?id=12&type=1', 'http://8.153.16.66:9000/dsh/142bc8240d974abe80ceee4a00fcf8b8.jpg', 0, '2024-10-25 12:39:40', '2024-10-25 12:40:18', NULL, NULL, 0);
INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (19, '追风筝的人', '9787208061644', 483, 3, '李继宏', 'The Kite Runner', 29.00, 362, NULL, '2006-05-01 08:00:00', NULL, NULL, 'http://demo.dianhuiyun.com.cn/dsh-client-h5/#/pages/forum/forum?id=14&type=1', 'http://8.153.16.66:9000/dsh/76f543d36650419297b0d2e754da5a36.jpg', 0, '2024-10-25 12:40:54', '2024-10-25 12:41:35', NULL, NULL, 0);
INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (20, '三国演义', '9787020008728', 511, 4, NULL, '罗贯中', 39.50, 990, '平装', '1998-05-01 08:00:00', '罗贯中（约1330—约1400），汉族，名本，字贯中，号湖海散人。山西太原人，一说钱塘（现在浙江杭州）或庐陵（现在江西吉安）人。元末明初著名小说家、戏曲家，是中国章回小说的鼻祖。', '《三国演义》又名《三国志演义》、《三国志通俗演义》，是我国小说史上最著名最杰出的长篇章回体历史小说。 ', 'http://demo.dianhuiyun.com.cn/dsh-client-h5/#/pages/forum/forum?id=15&type=1', 'http://8.153.16.66:9000/dsh/3022aaa1f1a148e09bc4e70068c80125.jpg', 0, '2024-10-25 12:41:44', '2024-10-25 12:42:10', NULL, NULL, 0);
INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (21, '呐喊', '9787201097206', 511, 8, NULL, '鲁迅', 32.00, 200, '平装', '2016-01-05 08:00:00', '鲁迅\n1881.9.25（农历八月廿八）-1936.10.19\n原名周树人，浙江绍兴人\n1904年赴日本仙台学医，后弃医从文，成为中国现代文学的奠基人', '《呐喊》是鲁迅的第一本小说集。1918年，新文化运动正值高峰。鲁迅因为和老朋友“金心异”（钱玄同）的一场关于“铁屋子”的谈话，创作了第一篇白话小说《狂人日记》。至1922年，五四大潮渐落，鲁迅应陈独秀之邀，将之前的小说结集出版，目的在于为新文化运动“呐喊”，并且慰藉那些在斗争中“奔驰的猛士”，使他们无畏地前进。', 'http://demo.dianhuiyun.com.cn/dsh-client-h5/#/pages/forum/forum?id=16&type=1', 'http://8.153.16.66:9000/dsh/ba1e15b36786464b9a0a2111ee18cba5.jpg', 0, '2024-10-25 12:43:58', '2024-10-25 12:44:25', NULL, NULL, 0);
INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (22, '天龙八部', '9787108006721', 511, 3, NULL, '金庸', 96.00, 1978, '平装', '1994-05-05 08:00:00', '金庸（1924年2月6日—），香港“大紫荆勋贤”。原名查良镛(zhā liáng yōng，英：Louis Cha)，浙江海宁人，当代著名作家、新闻学家、企业家、社会活动家，《香港基本法》主要起草人之一。金庸是新派武侠小说最杰出的代表作家，被普遍誉为武侠小说作家的“泰山北斗”，更有金迷们尊称其为“金大侠”或“查大侠”。', '天龙八部乃金笔下的一部长篇小说，与《射雕》，《神雕》等 几部长篇小说一起被称为可读性最高的金庸小说。《天龙》的故事情节曲折，内容丰富，也曾多次被改编为电视作品。是金庸作品中集大成的一部。故事以北宋末年动荡的社会环境为背景，展开波澜壮阔的历史画卷，塑造了乔峰、段誉、 虚竹、慕容复等形象鲜明的人物，成为武侠史上的经典之作。故事精彩纷呈，人物命运悲壮多变，是可读性很强的作品，具有震撼人心的力量', 'http://demo.dianhuiyun.com.cn/dsh-client-h5/#/pages/forum/forum?id=17&type=1', 'http://8.153.16.66:9000/dsh/b4558c29b87e45feaf6fa798c9a92b4f.jpg', 0, '2024-10-25 12:45:48', '2024-10-25 12:46:16', NULL, NULL, 0);
INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (23, '撒哈拉的故事', '9787806398791', 511, 8, NULL, '作者', 15.80, 217, '平装', '2003-08-01 08:00:00', '三毛（1943-1991），台湾作家。1943年3月26日出生于重庆，浙江省定海县人。本名为陈惠平，1946年改名陈平，笔名“三毛”。1964年入中国文化大学哲学系，肄业后曾留学欧洲，婚后定居西属撒哈拉沙漠加那利岛并以当地的生活为背景，写出一连串情感真挚的作品。1981年回到台湾，在中国文化大学任教，1984年辞去教职，专职从事写作和演讲。1991年1月4日自杀而死，终年48岁。', '三毛作品中最脍炙人口的《撒哈拉的故事》，由12篇精彩动人的散文结合而成，其中《沙漠中的饭店》，是三毛适应荒凉单调的沙漠生活后，重新拾笔的第一篇文字，自此之后，三毛便写出一系列以沙漠为背景的故事，倾倒了全世界的中文读者。', 'http://demo.dianhuiyun.com.cn/dsh-client-h5/#/pages/forum/forum?id=18&type=1', 'http://8.153.16.66:9000/dsh/e2c10661b7294278ae2d4aea81bdc8de.jpg', 0, '2024-10-25 12:48:10', '2024-10-25 12:48:46', NULL, NULL, 0);
INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (24, '野草', '9787201097190', 511, 4, NULL, '鲁迅', 29.00, 192, '平装', '2016-01-01 08:00:00', '鲁迅\n1881.9.25（农历八月廿八日）- 1936.10.19\n原名周树人，浙江绍兴人，“鲁迅”是他影响最为广泛的笔名。\n1904年赴日本仙台学医，后弃医从文，成为中国现代文学的奠基人。', '鲁迅曾经说过，自己一生的哲学都在《野草》里了。新版《野草》精选了74篇短小却意味深长的诗文，全书分四个部分，开篇完整再现《野草》，其余三个部分择选《华盖集》《准风月谈》《三闲集》《集外集》《且介亭杂文》中充满张力与魅力的短文。文章的张力，是人格的张力，写作的维度，也是人格的维度——愤怒、但是同时好玩；深刻、然而精通游戏；挑衅、却随时自嘲，批判……或许我们能从大先生的文字中领悟到自己的人生哲学。', 'http://demo.dianhuiyun.com.cn/dsh-client-h5/#/pages/forum/forum?id=19&type=1', 'http://8.153.16.66:9000/dsh/21bf892a8ec646ed9c53c529752838f7.jpg', 0, '2024-10-25 12:51:22', '2024-10-25 12:51:49', NULL, NULL, 0);
INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (25, '卡拉马佐夫兄弟  ', '9787532763696', 524, 7, NULL, '陀思妥耶夫斯基 (Ф.М.Достоевский)', 78.00, 985, '平装', '2015-02-04 08:00:00', '陀思妥耶夫斯基(1821-1881)，与大文豪列夫·托尔斯泰、屠格涅夫等人齐名，是俄国文学的卓越代表，他走的是一条极为艰辛、复杂的生活与创作道路，是俄国文学史上最复杂、最矛盾的，作家之一。他的创作独具特色，在群星灿烂的19世纪俄国文坛上独树一帜，占有着十分特殊的地位。主要作品有《穷人》、《被侮辱与被损害的》、《死屋手记》、《罪与罚》、《白痴》、《群魔》、《卡拉马佐夫兄弟》等。', '本书系俄国大作家陀思妥耶夫斯基代表作之一。小说通过一桩真实的弑父案，描写老卡拉马佐夫同三个儿子即两代人之间的尖锐冲突。老卡拉马佐夫贪婪好色，独占妻子留给儿子们的遗产，并与长子德米特里为一个风流女子争风吃醋。一天黑夜，德米特里疑心自己的情人去跟老头儿幽会，便闯入家园，一怒之下，差点儿把老头儿砸死。他仓皇逃离后，躲在暗中装病的老卡拉马佐夫的私生子斯乜尔加科夫，悄然杀死老爷，造成了一桩震惊全俄的扑朔迷离的血案，从而引发了一连串惊心动魄的事件。作品展示一个错综复杂的社会家庭、道德和人性的悲剧主题，体现了作家一生的最高艺术成就。', NULL, 'http://8.153.16.66:9000/dsh/5916fa9b17d040f0b6bab74eebc745c3.jpg', 0, '2024-10-25 12:55:15', '2024-10-25 12:55:40', NULL, NULL, 0);
