INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (42, '智能电网优化理论与应用', '9787564199265', 607, 3, NULL, '汤奕,王玉荣', 49.00, 319, '一般纯质纸', '2022-06-01 08:00:00', '汤奕是从事电力系统研究的学者，专注于智能电网技术、优化理论与算法应用。在相关领域发表了多篇学术论文，具有丰富的科研和实践经验。\n玉荣是电力工程领域的研究专家，对智能电网优化、可再生能源整合等主题有深入研究，曾参与多项国家级科研项目。', '随着智能电网建设的不断推进，电力系统领域的高比例新能源并网、特高压交直流混联架构、装置电力电子化、以及源网荷的协同控制等新特点给电力系统的规划、运行和控制带来了巨大挑战。而优化理论与方法近几年不仅在电力领域的应用方面具有极大需求，而且在人工智能等算法方面也取得了突破性进展。智能电网领域的优化理论方法及技术其应用具有很强的教学需求。本书具体内容包括：MATLAB应用基础，线性规划在电力系统中的应用；一维搜索；非线性规划在电力系统中的应用；非线性无约束问题的很优化方法；混合整数规划；智能算法在电力系统中的应用；基于人工智能算法的电力系统。', 'http://demo.dianhuiyun.com.cn/dsh-client-h5/#/pages/forum/forum?id=20&type=1', 'http://8.153.16.66:9000/dsh/f661b77ca34d4028966b50486296da9c.jpg', 0, '2024-12-16 15:49:10', '2024-12-20 13:08:49', '62b008d7479975793bf39cbb', 7, 0);
INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (43, '家庭照护', '9787576601282', 7, 3, NULL, '郭玲玲，朱晓卓', 58.00, NULL, NULL, '2022-06-01 08:00:00', '郭玲玲，江苏医药职业学院 护理学院副院长，硕士，副教授，从事护理职业教育16年，家政服务与管理职业教育8年。，朱晓卓：教授，现任宁波卫生职业技术学院高职研究所所长/健康服务与管理学院院长，宁波家政学院和宁波老年照护与管理学院执行院长，浙江省特色专业—现代家政服务与管理专业负责人，兼任中国家庭服务业协会理事、中国劳动学会理事，中国老教授协会家政学与家政产业专委会副主任委员，全国现代服务业产教融合联盟副秘书长/常务理事，浙江省家政服务产教融合联盟副秘书长/理事。宁波市哲学社会科学学科带头人、宁波市领军拔尖人才工程第二层次培养对象和浙江省高职高院校专业带头人，曾获得国家教学成果奖、宁波市教学成果奖等奖项，曾担任第二届全国巾帼家政风采大赛家政培训项目裁判长。', '这本书的编写一方面符合家政服务与管理专业人才培养方案的要求，同时融合学历教育与职业资格教育，加强家政服务与管理专业学生提升性岗位胜任力培养；另一方面也契合2000年8月劳动和社会保障部制定的《家政服务员国家职业标准》中家庭看护、看护老人、看护病人等方面的要求。根据家庭中与健康相关的知识、技能以及家庭中老人、病人等人群的照护特点及要求，教材内容本着简单、实用、够用、易操作的原则，设计了包括家政服务概述、家政服务员从业礼仪、家庭健康相关知识、家庭基本照护技术、家庭特殊照护技术、家庭常见疾病照护6个项目共35个任务，含盖了家政服务专业学生从业的基本要求，以及在居家照护中促进健康、维护健康、恢复健康的各种知识、技能。', 'http://demo.dianhuiyun.com.cn/dsh-client-h5/#/pages/forum/forum?id=21&type=1', 'http://8.153.16.66:9000/dsh/713bd72c4364408bb58bf46eaede330b.jpeg', 0, '2024-12-16 15:55:41', '2024-12-16 22:10:20', '629e9f15479975793bf39c1e', 7, 0);
INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (44, '农产品营销', '9787564198947', 446, 3, NULL, '何钢', 48.00, NULL, '平装', '2022-11-08 08:00:00', NULL, '面对农产品销售中“滞销、溅卖”等丰产不丰收“伤农”现象，消费者“高买”，优质农产品难求，一般农产品购买不放心等产销倒挂窘境的现象。本书从农产品经营者的视角，在营销技术层面，对农产品进行调研、环境分析，寻找机会，发掘销售途径；从策略层面，结合农产品特性，运用产品、价格、渠道、促销等策略打动消费者，开展营销活动。\n本书基于产教融合，大力开展实践教学与个性化学习，重点突出基本知识、基本技能和创新创业能力培养。根据农产品营销职业岗位统筹相关章节内容，每章节都以情景案例导入-基础知识与技能-学习评估的逻辑思路进行组织，并配套测试题、拓展实训、自我总结等体验学习内容，以实现“学中做、做中学、学以致用”的效果，职业教育特色鲜明。', 'http://demo.dianhuiyun.com.cn/dsh-client-h5/#/pages/forum/forum?id=24&type=1', 'http://8.153.16.66:9000/dsh/8f1aefde471346749ad0214aa503bb6d.jpg', 0, '2024-12-20 12:12:50', '2024-12-20 14:40:00', '629eab65479975793bf39c2b', 7, 0);
INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (45, '零售运营管理', '9787576600209', 446, 3, NULL, '钱鑫，沈于琛，阳金萍', 42.00, 219, '平装', '2022-07-15 08:00:00', '暂无', '依据人才培养方案，以零售企业的运营为主线，以提升零售企业绩效为目标，结合零售企业运营管理的实况，融合行业协会的职业标准，以中国慕课大学平台在线开放课程视频为辅助，教授学生零售运营认知、零售企业的组织结构、采购管理、商品陈列管理、库存管理、公共关系管理、实体门店管理、零售运营绩效管理等8个项目，使其掌握零售企业运营管理人员必备的基本知识和技能。', 'http://demo.dianhuiyun.com.cn/dsh-client-h5/#/pages/forum/forum?id=25&type=1', 'http://8.153.16.66:9000/dsh/2d63a824ac554a31b95b9dbb10d30e8c.jpg', 0, '2024-12-20 12:26:48', '2024-12-20 14:40:53', '63033d79bc0bbd467f566b16', 7, 0);
INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (46, '中医名家谈四季健康', '9787901004696', 9, 3, NULL, '马中凯', 0.00, NULL, NULL, '2024-12-11 08:00:00', NULL, '《中医名家谈四季健康》由马中凯主编，详细阐述了中医四季健康理念。书中按春、夏、秋、冬四季分别介绍养生要点，包括饮食调养、运动锻炼、情志调理等。强调顺应自然变化，调整生活方式，如春季养肝、夏季养心、秋季养肺、冬季养肾。通过具体食疗方、运动方法和情志调节技巧，指导读者科学养生，增强体质，预防疾病，享受健康快乐的生活。', 'http://demo.dianhuiyun.com.cn/dsh-client-h5/#/pages/forum/forum?id=26&type=1', 'http://8.153.16.66:9000/dsh/beb985f42dea43848e31a93b55eef1a9.jpg', 0, '2024-12-30 18:45:22', '2024-12-31 18:59:35', '', 0, 0);
INSERT INTO `book` (`id`, `book_name`, `isbn`, `classification_id`, `publisher_id`, `translator`, `writer`, `price`, `page_number`, `book_style`, `publish_date`, `author_introduction`, `book_introduction`, `forum_link`, `book_cover`, `delete_flag`, `create_time`, `update_time`, `other_id`, `wx_config_id`, `is_top`) VALUES (47, 'C++程序设计课程【第3版】', '978-7-111-55253-6', 607, 3, NULL, '刘绍翰', 49.00, NULL, '平装', '2016-12-06 08:00:00', '南京航空航天大学计算机学院教授，常年教授C++程序设计课程，经验丰富。', '本书包括两部分内容。第壹部分为第1~9章，以C++语言的基本语法为起点讲述面向过程的程序设计，内容包括基本数据类型、基本控制结构、函数、数组、结构体、指针和链表。第二部分为第10~15章，结合C++语言的应用实例，讲述面向对象程序设计的基本概念，内容包括类和对象、继承和派生、多态以及输入输出和文件操作。本书适用于程序设计语言的初学者，也适用于大学本科理工类各专业学习C++程序设计语言的学生，同时适用于自学C++语言的读者。\n', 'http://demo.dianhuiyun.com.cn/dsh-client-h5/#/pages/forum/forum?id=27&type=1', 'http://8.153.16.66:9000/dsh/1b24d0bea8204109a7baea9943b2961b.jpg', 0, '2025-03-31 10:21:00', '2025-03-31 11:19:06', '', 0, 0);
