INSERT INTO `category` (`id`, `name`, `description`, `delete_flag`, `create_time`, `update_time`, `parent_id`) VALUES (4, '文学', '文学类图书包括小说、诗歌、戏剧等。这类图书主要关注语言文字的艺术表现，通过故事情节、人物塑造和语言表达来反映生活、表达思想感情。', 0, '2024-08-14 19:41:25', '2024-08-14 19:41:48', 0);
INSERT INTO `category` (`id`, `name`, `description`, `delete_flag`, `create_time`, `update_time`, `parent_id`) VALUES (5, '科技', '科技类图书涵盖了科学技术各个领域的知识。包括物理、化学、生物、计算机、医学等学科的专著和科普读物。这类图书主要传递科学知识，介绍最新的科研成果和技术进展。', 0, '2024-08-14 19:41:43', '2024-08-14 19:41:43', 0);
INSERT INTO `category` (`id`, `name`, `description`, `delete_flag`, `create_time`, `update_time`, `parent_id`) VALUES (6, '社科', '社科类图书主要包括社会科学领域的著作。如历史、哲学、政治、经济、社会学等。这类图书主要研究社会现象、社会关系以及人类行为，提供对社会的深入理解和分析。', 0, '2024-08-14 19:42:03', '2024-08-14 19:42:03', 0);
INSERT INTO `category` (`id`, `name`, `description`, `delete_flag`, `create_time`, `update_time`, `parent_id`) VALUES (7, '教育', '教育类图书涵盖了各类教材和教辅书籍，以及针对不同年龄层次和学科的学习辅导书。还包括一些教育理论和教育方法的著作。', 0, '2024-08-14 19:42:18', '2024-08-14 19:42:18', 0);
INSERT INTO `category` (`id`, `name`, `description`, `delete_flag`, `create_time`, `update_time`, `parent_id`) VALUES (8, '艺术', '艺术类图书主要涉及音乐、美术、舞蹈、戏剧等艺术形式的相关书籍。包括艺术理论、艺术作品赏析以及艺术技巧教程等。', 0, '2024-08-14 19:42:36', '2024-08-14 19:42:36', 0);
INSERT INTO `category` (`id`, `name`, `description`, `delete_flag`, `create_time`, `update_time`, `parent_id`) VALUES (9, '生活', '生活类图书涉及日常生活的各个方面，如烹饪、养生、旅游、育儿等。这类图书主要提供生活指导和建议，帮助人们更好地生活。', 0, '2024-08-14 19:42:48', '2024-08-14 19:42:48', 0);
