INSERT INTO `forum` (`id`, `user_id`, `name`, `course_link`, `book_id`, `price`, `writer_introduction`, `voice_introduction`, `cover`, `avatar`, `delete_flag`, `create_time`, `update_time`, `other_book_id`, `is_top`) VALUES (1, 23, '哈利波特', NULL, 1, 50.00, 'J. K. 罗琳（J. K. Rowling， 1965- ），英国女作家，自小喜欢写作，当过短时间的教师和秘书。二十四岁那年，她在前往伦敦的火车旅途中萌生了创作“哈利·波特”系列小说的念头。七年后，《哈利·波特与魔法石》问世，之后她陆续创作了《哈利·波特与密室》《哈 利·波特与阿兹卡班囚徒》....', NULL, 'http://8.153.16.66:9000/dsh/3a8d4a68f1f84f65b53d9a300571a915.jpg', NULL, 0, '2024-10-25 11:33:12', '2024-10-25 11:34:07', NULL, 0);
INSERT INTO `forum` (`id`, `user_id`, `name`, `course_link`, `book_id`, `price`, `writer_introduction`, `voice_introduction`, `cover`, `avatar`, `delete_flag`, `create_time`, `update_time`, `other_book_id`, `is_top`) VALUES (2, 5, '红楼梦', NULL, 2, 22.90, '曹雪芹,（？-1763，一作1764）清小说家。名霑，字梦阮，号雪芹、芹圃、芹溪。为满洲正白旗“包衣”人。自曾祖起，三代任江宁织造，其祖曹寅尤为康熙帝所信用。雍正初年，在统计阶级内部政治斗争牵连下，雪芹家受到重大打击，其父免职，产业被抄，遂随家迁居北京。他早年经历了一段封建大官僚地主家庭的繁华生活，后因家道衰落，趋于艰困。晚期居北京西郊，贫病而卒，年未及五十。', NULL, 'http://8.153.16.66:9000/dsh/e62633bec51c42cbb267ef0cf3065f92.jpg', 'http://8.153.16.66:9000/dsh/92cefc0ee27f47199efbce104bdc83c6.png', 0, '2024-10-25 11:38:40', '2024-10-25 11:38:40', NULL, 0);
INSERT INTO `forum` (`id`, `user_id`, `name`, `course_link`, `book_id`, `price`, `writer_introduction`, `voice_introduction`, `cover`, `avatar`, `delete_flag`, `create_time`, `update_time`, `other_book_id`, `is_top`) VALUES (3, 5, '1984', NULL, 3, 5.00, '乔治•奥威尔（1903-1950）， 英国著名作家。主要作品有《动物农场》、《1984》等。\n\n1903年出生于印度，1907年举家迁回英国，后因经济原因无力深造，被迫远走缅甸，参加帝国警察部队。终因厌倦殖民行径、痴迷写作而辞去公职，辗转回到欧洲，流亡伦敦、巴黎等地，一边深刻体验下层民众生活，一遍从事文学创作，有多部作品出版。1936年西班牙内战爆发，参加左翼组织....', NULL, 'http://8.153.16.66:9000/dsh/593cc31094304713aa4b5da78c024fdf.jpg', NULL, 0, '2024-10-25 12:14:33', '2024-10-25 12:14:33', NULL, 0);
INSERT INTO `forum` (`id`, `user_id`, `name`, `course_link`, `book_id`, `price`, `writer_introduction`, `voice_introduction`, `cover`, `avatar`, `delete_flag`, `create_time`, `update_time`, `other_book_id`, `is_top`) VALUES (4, 23, 'Java编程讨论', NULL, 7, 15.00, 'Bruce Eckel是MindView公司（www.MindView.net）的总裁，该公司向客户提供软件咨询和培训。他是C++标准委员会拥有表决权的成员之一，拥有应用物理学学士和计算机工程硕士学位。除本书外，他还是《C++编程思想》的作者，并与人合著了《C++编程思想 第2卷》（这两本书的英文影印版及中文版均已由机械工业出版社引进出版）及其他著作。他已经发表了150多篇论文，还经常参加世界各地的研讨会并进行演讲。', NULL, 'http://8.153.16.66:9000/dsh/293ae7d4178940fa985e8776c695da8c.jpg', NULL, 0, '2024-10-25 12:26:54', '2024-10-25 12:26:54', NULL, 0);
INSERT INTO `forum` (`id`, `user_id`, `name`, `course_link`, `book_id`, `price`, `writer_introduction`, `voice_introduction`, `cover`, `avatar`, `delete_flag`, `create_time`, `update_time`, `other_book_id`, `is_top`) VALUES (5, 11, '活着', NULL, 4, 5.00, '余华，1960年出生，1983年开始写作。至今已经出版长篇小说4部，中短篇小说集6部，随笔集4部。主要作品有《兄弟》《活着》《许三观卖血记》《在细雨中呼喊》等。', NULL, 'http://8.153.16.66:9000/dsh/4c9ad4d95a71424496368a5c7b08dad4.jpg', 'http://8.153.16.66:9000/dsh/cd1b0e0b512846b5b002a826007e0eab.png', 0, '2024-10-25 12:28:32', '2024-10-25 12:28:32', NULL, 0);
INSERT INTO `forum` (`id`, `user_id`, `name`, `course_link`, `book_id`, `price`, `writer_introduction`, `voice_introduction`, `cover`, `avatar`, `delete_flag`, `create_time`, `update_time`, `other_book_id`, `is_top`) VALUES (6, 11, '百年孤独', NULL, 5, 10.00, '加西亚•马尔克斯（Gabriel García Márquez）1927年出生于哥伦比亚马格达莱纳海滨小镇阿拉卡塔卡。童年与外祖父母一起生活。1936年随父母迁居苏克雷。1947年考入波哥大国立大学。1948年因内战辍学，进入报界。五十年代开始发表文学作品。六十年代初移居墨西哥。1967年出版《百年孤独》。1982年获诺贝尔文学奖。', NULL, 'http://8.153.16.66:9000/dsh/1cf64a16afb949bb8854c0c49001a062.jpg', NULL, 0, '2024-10-25 12:35:51', '2024-10-25 12:35:51', NULL, 0);
INSERT INTO `forum` (`id`, `user_id`, `name`, `course_link`, `book_id`, `price`, `writer_introduction`, `voice_introduction`, `cover`, `avatar`, `delete_flag`, `create_time`, `update_time`, `other_book_id`, `is_top`) VALUES (7, 14, '三体', NULL, 16, 12.00, '中国当代科幻小说的主要代表作家，被誉为中国科幻文学的领军人物。中国科普作家协会会员，中国作家协会会员，山西省作家协会会员，2013年中国作家富豪榜上榜作家。自上世纪九十年代开始发表科幻作品，曾于1999年至2006年连续八年获得中国科幻银河奖，作品因宏伟大气、想象绚丽而获得广泛赞誉。', NULL, 'http://8.153.16.66:9000/dsh/4ade4cd43aeb4b1abc168a6599b38b61.jpg', NULL, 0, '2024-10-25 12:36:44', '2024-10-25 12:36:44', NULL, 0);
INSERT INTO `forum` (`id`, `user_id`, `name`, `course_link`, `book_id`, `price`, `writer_introduction`, `voice_introduction`, `cover`, `avatar`, `delete_flag`, `create_time`, `update_time`, `other_book_id`, `is_top`) VALUES (8, 14, '飘', NULL, 6, 5.00, '米切尔（Margaret Mitchell, 1900-1949）美国女作家。出生于美国南部佐治亚州亚特兰大市。父亲是个律师，曾任亚特兰大历史协会主席。米切尔曾就读于华盛顿神学院、马萨诸塞州的史密斯学院。其后，她曾担任地方报纸《亚特兰大报》的记者。1925年与约翰·马尔什结婚，婚后辞去报职，潜心写作。\n\n米切尔一生中只发表了《飘》这部长篇巨著。她从1926年开始着力创作《飘》，10 年之后，作品问世，一出版就引起了强烈的反响。', NULL, 'http://8.153.16.66:9000/dsh/33d72968c17b42598f8ea983350def3d.jpg', NULL, 0, '2024-10-25 12:36:57', '2024-10-25 12:36:57', NULL, 0);
INSERT INTO `forum` (`id`, `user_id`, `name`, `course_link`, `book_id`, `price`, `writer_introduction`, `voice_introduction`, `cover`, `avatar`, `delete_flag`, `create_time`, `update_time`, `other_book_id`, `is_top`) VALUES (9, 15, '动物农场', NULL, 8, 6.00, '乔治·奥威尔（George Orwell），本名埃里克·亚瑟·布莱尔（Eric Arthur Blair）。1903年生于印度，当时，他的父亲在当地的殖民地政府供职，用他自己的话说，他家属于“中产阶级的下层，或没有钱财的中产家庭”。\n\n1904年，由母亲带他先回到了英国。他自幼天资聪颖，11岁时就在报纸上发表了一篇诗作《醒来吧，英格兰的小伙子们》。14岁又考入著名的伊顿（Eton）公学，并获取了奖学金....', NULL, 'http://8.153.16.66:9000/dsh/69361dd2b9c9452492e8e4c35e44e135.jpg', NULL, 0, '2024-10-25 12:38:01', '2024-10-25 12:38:01', NULL, 0);
INSERT INTO `forum` (`id`, `user_id`, `name`, `course_link`, `book_id`, `price`, `writer_introduction`, `voice_introduction`, `cover`, `avatar`, `delete_flag`, `create_time`, `update_time`, `other_book_id`, `is_top`) VALUES (10, 21, '白夜行', NULL, 9, 12.00, '东野圭吾\n\n日本著名作家。\n\n1985年，凭《放学后》获第31届江户川乱步奖，开始专职写作；\n\n1999年，《秘密》获第52届日本推理作家协会奖；此后《白夜行》、《单恋》、《信》、《幻夜》先后入围直木奖。\n\n2005年出版的《嫌疑人X的献身》史无前例地将第134届直木奖、第6届本格推理小说大奖，以及年度三大推理小说排行榜第1名一并斩获；\n\n2008年，《流星之绊》获第43届新风奖。\n\n2009年出版的《新参者》获两大推理小说排行榜年度第1名；\n\n2012年，《浪矢杂货店的奇迹》获第7届中央公论文艺奖。', NULL, 'http://8.153.16.66:9000/dsh/3db26fcdf4214cc6993ab03522cb5c44.jpg', NULL, 0, '2024-10-25 12:38:42', '2024-10-25 12:38:42', NULL, 0);
INSERT INTO `forum` (`id`, `user_id`, `name`, `course_link`, `book_id`, `price`, `writer_introduction`, `voice_introduction`, `cover`, `avatar`, `delete_flag`, `create_time`, `update_time`, `other_book_id`, `is_top`) VALUES (11, 19, '杀死一只知更鸟', NULL, 10, 5.00, '哈珀•李（1926— ）\n\n生于美国阿拉巴马州， 曾被授予普利策小说奖及其他众多文学奖项。她与杜鲁门•卡坡蒂是幼年的邻居和一生的朋友。《杀死一只知更鸟》据说是以卡坡蒂为原型之一创作的，现已成为公认的美国文学经典。此后，她一直隐居在家乡亚拉巴马的小镇上 ，拒绝各种采访，过着平静的生活。有人问她为什么不在盛名之下接着写作，她回答：“有过这样一次，还有什么可写的？”', NULL, 'http://8.153.16.66:9000/dsh/e2c5207b4c8a47ed8a04f6ac65c4e29b.jpg', NULL, 0, '2024-10-25 12:39:30', '2024-10-25 12:39:30', NULL, 0);
INSERT INTO `forum` (`id`, `user_id`, `name`, `course_link`, `book_id`, `price`, `writer_introduction`, `voice_introduction`, `cover`, `avatar`, `delete_flag`, `create_time`, `update_time`, `other_book_id`, `is_top`) VALUES (12, 17, '房思琪的初恋乐园', NULL, 18, 4.00, '林奕含（1991——2017），台湾作家。出生于台南，曾居台北。梦想是一面写小说，一面像大江健三郎所说的：从书呆子变成读书人，再从读书人变成知识分子。', NULL, 'http://8.153.16.66:9000/dsh/1ca172253b104e2fb74bda242f023cdb.jpg', NULL, 0, '2024-10-25 12:40:19', '2024-10-25 12:40:19', NULL, 0);
INSERT INTO `forum` (`id`, `user_id`, `name`, `course_link`, `book_id`, `price`, `writer_introduction`, `voice_introduction`, `cover`, `avatar`, `delete_flag`, `create_time`, `update_time`, `other_book_id`, `is_top`) VALUES (13, 17, '局外人', NULL, 17, 11.00, '阿尔贝·加缪（Albert Camus，1913—1960），法国声名卓著的小说家、散文家和剧作家，“存在主义”文学的大师。1957年因“热情而冷静地阐明了当代向人类良知提出的种种问题”而获诺贝尔文学奖，是有史以来最年轻的诺奖获奖作家之一。加缪在他的小说、戏剧、随笔和论著中深刻地揭示出人在异己的世界中的孤独、个人与自身的日益异化....', NULL, 'http://8.153.16.66:9000/dsh/70b0459b88ab4305b6dced7bd008bf16.jpg', NULL, 0, '2024-10-25 12:40:25', '2024-10-25 12:40:25', NULL, 0);
INSERT INTO `forum` (`id`, `user_id`, `name`, `course_link`, `book_id`, `price`, `writer_introduction`, `voice_introduction`, `cover`, `avatar`, `delete_flag`, `create_time`, `update_time`, `other_book_id`, `is_top`) VALUES (14, 6, '追风筝的人', NULL, 19, 43.00, '卡勒德·胡赛尼（Khaled Hosseini），1965年生于阿富汗喀布尔市，后随父亲迁往美国。胡赛尼毕业于加州大学圣地亚哥医学系，现居加州。“立志拂去蒙在阿富汗普通民众面孔的尘灰，将背后灵魂的悸动展示给世人。', NULL, 'http://8.153.16.66:9000/dsh/3ce6df216be74d1d9054e8b7c430fc32.jpg', NULL, 0, '2024-10-25 12:41:36', '2024-10-25 12:41:36', NULL, 0);
INSERT INTO `forum` (`id`, `user_id`, `name`, `course_link`, `book_id`, `price`, `writer_introduction`, `voice_introduction`, `cover`, `avatar`, `delete_flag`, `create_time`, `update_time`, `other_book_id`, `is_top`) VALUES (15, 21, '三国演义', NULL, 20, 33.00, '罗贯中（约1330—约1400），汉族，名本，字贯中，号湖海散人。山西太原人，一说钱塘（现在浙江杭州）或庐陵（现在江西吉安）人。元末明初著名小说家、戏曲家，是中国章回小说的鼻祖。', NULL, 'http://8.153.16.66:9000/dsh/63d2de1f34ec4ecc9acc46a06e0a15d6.jpg', NULL, 0, '2024-10-25 12:42:10', '2024-10-25 12:42:10', NULL, 0);
INSERT INTO `forum` (`id`, `user_id`, `name`, `course_link`, `book_id`, `price`, `writer_introduction`, `voice_introduction`, `cover`, `avatar`, `delete_flag`, `create_time`, `update_time`, `other_book_id`, `is_top`) VALUES (16, 16, '呐喊', NULL, 21, 1.00, '鲁迅\n1881.9.25（农历八月廿八）-1936.10.19\n原名周树人，浙江绍兴人\n1904年赴日本仙台学医，后弃医从文，成为中国现代文学的奠基人', NULL, 'http://8.153.16.66:9000/dsh/734498ad4e4845d093da0032371073fe.jpg', NULL, 0, '2024-10-25 12:44:26', '2024-10-25 12:44:26', NULL, 0);
INSERT INTO `forum` (`id`, `user_id`, `name`, `course_link`, `book_id`, `price`, `writer_introduction`, `voice_introduction`, `cover`, `avatar`, `delete_flag`, `create_time`, `update_time`, `other_book_id`, `is_top`) VALUES (17, 20, '天龙八部', NULL, 22, 88.00, '金庸（1924年2月6日—），香港“大紫荆勋贤”。原名查良镛(zhā liáng yōng，英：Louis Cha)，浙江海宁人，当代著名作家、新闻学家、企业家、社会活动家，《香港基本法》主要起草人之一。金庸是新派武侠小说最杰出的代表作家，被普遍誉为武侠小说作家的“泰山北斗”，更有金迷们尊称其为“金大侠”或“查大侠”。', NULL, 'http://8.153.16.66:9000/dsh/1d0a7a2777f646d9971d11d9933c1a24.jpg', NULL, 0, '2024-10-25 12:46:17', '2024-10-25 12:46:17', NULL, 0);
INSERT INTO `forum` (`id`, `user_id`, `name`, `course_link`, `book_id`, `price`, `writer_introduction`, `voice_introduction`, `cover`, `avatar`, `delete_flag`, `create_time`, `update_time`, `other_book_id`, `is_top`) VALUES (18, 29, '撒哈拉的故事', NULL, 23, 1.00, '三毛（1943-1991），台湾作家。1943年3月26日出生于重庆，浙江省定海县人。本名为陈惠平，1946年改名陈平，笔名“三毛”。1964年入中国文化大学哲学系，肄业后曾留学欧洲，婚后定居西属撒哈拉沙漠加那利岛并以当地的生活为背景，写出一连串情感真挚的作品。1981年回到台湾，在中国文化大学任教，1984年辞去教职，专职从事写作和演讲。1991年1月4日自杀而死，终年48岁。', NULL, 'http://8.153.16.66:9000/dsh/cab5faa935bb466bac106a84315a84db.jpg', NULL, 0, '2024-10-25 12:48:47', '2024-10-25 12:48:47', NULL, 0);
INSERT INTO `forum` (`id`, `user_id`, `name`, `course_link`, `book_id`, `price`, `writer_introduction`, `voice_introduction`, `cover`, `avatar`, `delete_flag`, `create_time`, `update_time`, `other_book_id`, `is_top`) VALUES (19, 29, '野草', NULL, 24, 11.00, '鲁迅\n1881.9.25（农历八月廿八日）- 1936.10.19\n原名周树人，浙江绍兴人，“鲁迅”是他影响最为广泛的笔名。\n1904年赴日本仙台学医，后弃医从文，成为中国现代文学的奠基人。', NULL, 'http://8.153.16.66:9000/dsh/1e97b38094804085b433efeb9fa66269.jpg', NULL, 0, '2024-10-25 12:51:50', '2024-10-25 12:51:50', NULL, 0);
INSERT INTO `forum` (`id`, `user_id`, `name`, `course_link`, `book_id`, `price`, `writer_introduction`, `voice_introduction`, `cover`, `avatar`, `delete_flag`, `create_time`, `update_time`, `other_book_id`, `is_top`) VALUES (22, 6, '智能电网优化理论与应用', NULL, 42, 10.00, '汤奕是从事电力系统研究的学者，专注于智能电网技术、优化理论与算法应用。在相关领域发表了多篇学术论文，具有丰富的科研和实践经验。\n王玉荣是电力工程领域的研究专家，对智能电网优化、可再生能源整合等主题有深入研究，曾参与多项国家级科研项目。', NULL, 'http://8.153.16.66:9000/dsh/405f651cf56542b995685437bf7f8721.jpg', NULL, 0, '2024-12-16 15:58:48', '2024-12-16 15:58:48', '62b008d7479975793bf39cbb', 0);
INSERT INTO `forum` (`id`, `user_id`, `name`, `course_link`, `book_id`, `price`, `writer_introduction`, `voice_introduction`, `cover`, `avatar`, `delete_flag`, `create_time`, `update_time`, `other_book_id`, `is_top`) VALUES (23, 6, '家庭照护', NULL, 43, 58.00, '郭玲玲，江苏医药职业学院 护理学院副院长，硕士，副教授，从事护理职业教育16年，家政服务与管理职业教育8年。，朱晓卓：教授，现任宁波卫生职业技术学院高职研究所所长/健康服务与管理学院院长，宁波家政学院和宁波老年照护与管理学院执行院长，浙江省特色专业—现代家政服务与管理专业负责人，兼任中国家庭服务业协会理事、中国劳动学会理事，中国老教授协会家政学与家政产业专委会副主任委员，全国现代服务业产教融合联盟副秘书长/常务理事，浙江省家政服务产教融合联盟副秘书长/理事。', NULL, 'http://8.153.16.66:9000/dsh/7de5b1112a1e4b38b48f4d90a4e80d37.jpeg', NULL, 0, '2024-12-16 15:59:43', '2024-12-16 16:38:14', '629e9f15479975793bf39c1e', 0);
INSERT INTO `forum` (`id`, `user_id`, `name`, `course_link`, `book_id`, `price`, `writer_introduction`, `voice_introduction`, `cover`, `avatar`, `delete_flag`, `create_time`, `update_time`, `other_book_id`, `is_top`) VALUES (24, 20, '农产品营销', NULL, 44, 48.00, '暂无', NULL, 'http://8.153.16.66:9000/dsh/1a57fb2446324b21b5bf9a266551eeee.jpg', NULL, 0, '2024-12-20 12:15:05', '2024-12-20 12:15:22', '629eab65479975793bf39c2b', 0);
INSERT INTO `forum` (`id`, `user_id`, `name`, `course_link`, `book_id`, `price`, `writer_introduction`, `voice_introduction`, `cover`, `avatar`, `delete_flag`, `create_time`, `update_time`, `other_book_id`, `is_top`) VALUES (25, 6, '零售运营管理', NULL, 45, 42.00, '暂无', NULL, 'http://8.153.16.66:9000/dsh/2d3751637fbd4e759dbe6490e70601a1.jpg', NULL, 0, '2024-12-20 12:27:45', '2024-12-20 14:41:35', '63033d79bc0bbd467f566b16', 0);
INSERT INTO `forum` (`id`, `user_id`, `name`, `course_link`, `book_id`, `price`, `writer_introduction`, `voice_introduction`, `cover`, `avatar`, `delete_flag`, `create_time`, `update_time`, `other_book_id`, `is_top`) VALUES (26, 23, '中医名家谈四季健康', NULL, 46, 0.00, '马中凯 中医丹道医学传承者 中医过敏皮肤病专家\n原北大国医馆主任，中医皮肤病、过敏性疾病资深专家，内科疑难病专家。\n先后被派往世界多地行医井传播中医文化。近几年受司仁堂道请前往东南亚地区，为包括王室和普通民众在内的各界患者诊行。运用独特的丹道医学理论指导临床实钱、收到良好的医疗效果、受到当地思者的一致攻迎和好评、并接受国内外多家媒体的采访.', NULL, 'http://8.153.16.66:9000/dsh/b443e86b581b4166a2ca03adda706e11.jpg', NULL, 0, '2024-12-30 18:47:53', '2024-12-30 18:49:04', NULL, 0);
