-- ----------------------------
-- Table structure for sys_content_audit
-- ----------------------------
DROP TABLE IF EXISTS `sys_content_audit`;
CREATE TABLE `sys_content_audit` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核名称',
  `type` int NOT NULL COMMENT '审核类型: 0-短视频，1-离线视频，2-图书文字，3-图书插图',
  `url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Oss文件地址',
  `file_size` double DEFAULT '0' COMMENT '文件大小',
  `duration` int DEFAULT NULL COMMENT '视频时长',
  `audit_start_time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '审核开始时间，corn表达式',
  `execute_result` int NOT NULL COMMENT '-1:未执行，0:执行一次，1:执行成功',
  `execute_status` int NOT NULL COMMENT '执行状态：0-未执行，1-执行中，2-执行结束',
  `execute_type` int NOT NULL COMMENT '执行类型：0-立刻执行，1-定时执行',
  `delete_flag` int NOT NULL COMMENT '删除标志：0-未删除，1-已删除',
  `create_time` datetime NOT NULL,
  `update_time` datetime NOT NULL ON UPDATE CURRENT_TIMESTAMP,
  `local_file_info` varchar(600) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '本地文件信息',
  `file_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

