-- ----------------------------
-- Table structure for t_config
-- ----------------------------
DROP TABLE IF EXISTS `t_config`;
CREATE TABLE `t_config` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '配置名称',
  `type` int NOT NULL COMMENT '配置类型：0-公众号配置，1-其他配置',
  `create_time` datetime NOT NULL,
  `update_time` datetime NOT NULL ON UPDATE CURRENT_TIMESTAMP,
  `delete_flag` int NOT NULL DEFAULT '0' COMMENT '删除标志',
  `account` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '账号',
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '密码',
  `publisher_id` int NOT NULL COMMENT '出版社id',
  `logo` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '公众号logo',
  `resource_get_type` int NOT NULL DEFAULT '0' COMMENT '0: 公众号内容获取, 1:书籍内获取',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

